function applyGlobalLanguage(language: Language) {
  if (typeof document === 'undefined') return
  const translate = (value: string) => globalUiTranslations[value]?.[language] ?? value
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT)
  const nodes: Text[] = []
  while (walker.nextNode()) nodes.push(walker.currentNode as Text)
  nodes.forEach(node => { const current = node.nodeValue?.trim(); if (!current) return; const original = node.parentElement?.getAttribute('data-civic-original') ?? current; node.parentElement?.setAttribute('data-civic-original', original); if (globalUiTranslations[original]) node.nodeValue = node.nodeValue?.replace(current, translate(original)) ?? node.nodeValue })
  document.querySelectorAll<HTMLInputElement>('[placeholder], [aria-label]').forEach(element => { const attribute = element.hasAttribute('placeholder') ? 'placeholder' : 'aria-label'; const value = element.getAttribute(attribute); if (!value) return; const original = element.getAttribute(`data-civic-${attribute}`) ?? value; element.setAttribute(`data-civic-${attribute}`, original); if (globalUiTranslations[original]) element.setAttribute(attribute, translate(original)) })
}

function Logo() { return <div className="brand"><div className="brand-mark"><ShieldCheck /></div><div><div className="brand-name">Civic<span>Connect</span></div><div className="brand-sub">Your voice. Our action.</div></div></div> }
function StatusBadge({ status }: { status: Status }) { const tone = status === 'Resolved' || status === 'Closed' ? 'success' : status === 'In Progress' ? 'info' : status === 'Under Verification' ? 'warning' : 'neutral'; return <span className={`status-badge ${tone}`}><span className="status-dot" />{status}</span> }
function PriorityBadge({ priority }: { priority: Issue['priority'] }) { return <span className={`priority-badge ${priorityClasses[priority]}`}><span className="priority-dot" />{priority}</span> }
function MapPanel({ compact = false }: { compact?: boolean }) { const markers = [{ left: '19%', top: '36%', type: 'critical' }, { left: '57%', top: '26%', type: 'high' }, { left: '43%', top: '61%', type: 'high' }, { left: '76%', top: '53%', type: 'medium' }, { left: '30%', top: '75%', type: 'resolved' }]; return <div className={`map-panel ${compact ? 'map-compact' : ''}`}><div className="map-grid" /><div className="map-road road-a" /><div className="map-road road-b" /><div className="map-road road-c" />{markers.map((marker, index) => <button aria-label={`${marker.type} issue marker`} className={`map-marker marker-${marker.type}`} style={{ left: marker.left, top: marker.top }} key={index}>{marker.type === 'critical' ? '!' : ''}</button>)}<div className="map-card"><div className="map-card-title"><MapPin /> Live civic issues</div><div className="map-card-count">24 <span>in your area</span></div><div className="map-legend"><span><i className="legend-dot critical" />Critical</span><span><i className="legend-dot high" />High</span><span><i className="legend-dot medium" />Medium</span></div></div>{!compact && <button className="map-location"><LocateFixed /> Use my location</button>}</div> }
function IssueCard({ issue }: { issue: Issue }) { const [supported, setSupported] = useState(false); return <article className="issue-card"><div className="issue-card-top"><div className="issue-category"><span className="category-icon category-teal">{issue.category === 'Water Supply' ? <Droplets /> : issue.category === 'Garbage' ? <Trash2 /> : issue.category === 'Streetlight' ? <Lightbulb /> : <Road />}</span><span>{issue.category}</span></div><PriorityBadge priority={issue.priority} /></div><h3>{issue.title}</h3><p className="issue-location"><MapPin />{issue.location}</p><div className="issue-card-meta"><span><UserRound /> {issue.affected} affected</span><span><FileText /> {issue.reports} reports</span></div><div className="issue-card-footer"><StatusBadge status={issue.status} /><button className={`support-button ${supported ? 'is-supported' : ''}`} onClick={() => setSupported(!supported)}><ThumbsUp /> {supported ? 'Supporting' : 'I am also affected'}</button></div></article> }

function VoiceRecorder({ language, onTranscript }: { language: Language; onTranscript: (value: string) => void }) { const [recording, setRecording] = useState(false); const [transcript, setTranscript] = useState(''); const [error, setError] = useState(''); const [followUp, setFollowUp] = useState(''); const recognitionRef = useRef<RecognitionLike | null>(null); const start = () => { const Recognition = (window as unknown as { SpeechRecognition?: new () => RecognitionLike; webkitSpeechRecognition?: new () => RecognitionLike }).SpeechRecognition || (window as unknown as { webkitSpeechRecognition?: new () => RecognitionLike }).webkitSpeechRecognition; if (Recognition) { const recognition = new Recognition(); recognition.lang = language === 'TE' ? 'te-IN' : language === 'HI' ? 'hi-IN' : 'en-IN'; recognition.continuous = false; recognition.interimResults = false; recognition.onresult = (event: { results: { [index: number]: { [index: number]: { transcript: string } } } }) => { const value = event.results[0][0].transcript; setTranscript(value); setError(''); onTranscript(value); void fetch('/api/issue-understanding', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ transcript: value, language }) }).then(response => response.ok ? response.json() : null).then(result => { if (result?.followUpQuestion) setFollowUp(result.followUpQuestion) }).catch(() => undefined) }; recognition.onend = () => setRecording(false); recognition.start(); recognitionRef.current = recognition; setRecording(true) } else { setTranscript(''); setRecording(false); setError('Speech recognition is not supported in this browser. You can type your report instead.'); } }; const stop = () => { recognitionRef.current?.stop(); setRecording(false) }; return <div className="voice-assistant"><div className="voice-assistant-head"><div><p className="eyebrow">{language === 'TE' ? 'వాయిస్ సహాయకుడు' : language === 'HI' ? 'वॉइस सहायक' : 'Multilingual voice assistant'}</p><h3><Mic /> {translations[language].voice}</h3></div><span className={recording ? 'recording-pill active' : 'recording-pill'}>{recording ? 'Listening…' : 'Ready'}</span></div><p className="voice-help">Speak naturally in English, తెలుగు or हिन्दी. We will fill the report for you.</p><div className="voice-actions">{recording ? <Button type="button" variant="outline" onClick={stop}><X data-icon="inline-start" /> {translations[language].stop}</Button> : <Button type="button" className="voice-record-button" onClick={start}><Mic data-icon="inline-start" /> {translations[language].start}</Button>}{transcript && <Button type="button" variant="ghost" onClick={() => { setTranscript(''); onTranscript('') }}><RotateIcon /> {translations[language].again}</Button>}</div>{transcript && <div className="transcript-box"><span>Recognized speech</span><strong>{transcript}</strong><small>Review the text before submitting.</small></div>}</div> }
function RotateIcon() { return <span aria-hidden="true">↻</span> }

function FieldVoice({ language, label, value, onChange, onUnderstand, multiline = false }: { language: Language; label: string; value: string; onChange: (value: string) => void; onUnderstand?: (result: { category?: string; problem?: string; location?: string; followUpQuestion?: string | null }) => void; multiline?: boolean }) { const [open, setOpen] = useState(false); const [recording, setRecording] = useState(false); const [transcript, setTranscript] = useState(''); const [message, setMessage] = useState(''); const recognitionRef = useRef<RecognitionLike | null>(null); const start = () => { setOpen(true); setMessage(''); const Recognition = (window as unknown as { SpeechRecognition?: new () => RecognitionLike; webkitSpeechRecognition?: new () => RecognitionLike }).SpeechRecognition || (window as unknown as { webkitSpeechRecognition?: new () => RecognitionLike }).webkitSpeechRecognition; if (!Recognition) { setMessage('Microphone permission or speech recognition is not available. You can type instead.'); return } const recognition = new Recognition(); recognition.lang = language === 'TE' ? 'te-IN' : language === 'HI' ? 'hi-IN' : 'en-IN'; recognition.continuous = false; recognition.interimResults = false; recognition.onresult = (event: { results: { [index: number]: { [index: number]: { transcript: string } } } }) => { const spoken = event.results[0][0].transcript; setTranscript(spoken); onChange(spoken); void fetch('/api/issue-understanding', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ transcript: spoken, language }) }).then(response => response.ok ? response.json() : null).then(result => { if (result) { onUnderstand?.(result); setMessage(result.followUpQuestion || 'I understood this. You can edit it or confirm.'); } else setMessage("I couldn't understand. Please speak again.") }).catch(() => setMessage("I couldn't understand. Please speak again.")) }; recognition.onerror = () => { setRecording(false); setMessage('Microphone permission is required for voice input. You can type instead.'); }; recognition.onend = () => setRecording(false); try { recognition.start(); setRecording(true); recognitionRef.current = recognition } catch { setMessage('Please allow microphone access, then speak again.') } }; const close = () => { recognitionRef.current?.stop(); setRecording(false); setOpen(false) }; return <div className="field-voice-wrap"><div className="field-voice-control">{multiline ? <textarea value={value} onChange={event => onChange(event.target.value)} placeholder={label} aria-label={label} /> : <input value={value} onChange={event => onChange(event.target.value)} placeholder={label} aria-label={label} />}<button type="button" className={`field-mic ${recording ? 'is-recording' : ''}`} aria-label={`Speak for ${label}`} onClick={start}><Mic /></button></div>{open && <div className="field-voice-panel" role="dialog" aria-label={`Civic Assistant for ${label}`}><div className="field-voice-panel-head"><strong>Civic Assistant</strong><button type="button" aria-label="Close voice assistant" onClick={close}><X /></button></div><p>{recording ? 'Listening...' : 'Tell me about this field.'}</p>{transcript && <div className="field-transcript">{transcript}</div>}{message && <small>{message}</small>}<div className="field-voice-actions"><button type="button" onClick={start}><RotateIcon /> Speak Again</button><button type="button" onClick={close}><Check /> Confirm</button></div></div>}</div> }

function ReportForm({ language, onSubmit }: { language: Language; onSubmit: (issue: Issue) => void }) { const t = translations[language]; const [category, setCategory] = useState(''); const [description, setDescription] = useState(''); const [location, setLocation] = useState(''); const [details, setDetails] = useState(''); const [severity, setSeverity] = useState('High'); const [affected, setAffected] = useState(''); const [files, setFiles] = useState<File[]>([]); const [submitted, setSubmitted] = useState(false); const handleFiles = (event: React.ChangeEvent<HTMLInputElement>) => { const selected = Array.from(event.target.files ?? []).filter(file => /^(image\/(jpeg|png|webp)|video\/(mp4|quicktime|webm))$/.test(file.type) && file.size <= 25 * 1024 * 1024); setFiles(previous => [...previous, ...selected].slice(0, 5)); event.target.value = '' }; const categories = ['Road / Pothole', 'Water Supply', 'Drainage', 'Garbage', 'Streetlight', 'Electricity', 'Sewage', 'Public Toilet', 'Public Safety', 'Other']; const submit = (event: React.FormEvent) => { event.preventDefault(); const id = `CIV-${10300 + Math.floor(Math.random() * 100)}`; onSubmit({ id, title: description || `${category || 'Civic'} issue`, category: category || 'Other', location: location || 'Location shared from map', priority: severity as Issue['priority'], status: 'New', affected: Number(affected) || 1, reports: 1, date: 'Just now', department: category === 'Water Supply' ? 'Water Department' : category === 'Garbage' ? 'Sanitation' : 'Municipality', officer: 'Awaiting assignment', score: 64, color: 'high' }); setSubmitted(true) }; if (submitted) return <div className="submitted-state"><div className="submitted-icon"><CheckCircle2 /></div><p className="eyebrow">Report received</p><h2>Thank you for speaking up.</h2><p>Your issue is now in the civic response queue. We will keep you updated.</p><Button className="button-primary" onClick={() => { setSubmitted(false); setCategory(''); setDescription(''); setLocation(''); setDetails('') }}>Report another issue <ArrowRight data-icon="inline-end" /></Button></div>; return <form className="report-form" onSubmit={submit}><div className="step-list"><div className="form-step"><span>1</span><div><strong>Issue category</strong><p>Choose a category or speak naturally.</p><div className="field-voice-control"><select value={category} onChange={event => setCategory(event.target.value)} aria-label="Select Issue Category"><option value="">Select Issue Category</option>{categories.map(item => <option key={item}>{item}</option>)}</select><FieldVoice language={language} label="Select Issue Category" value={category} onChange={setCategory} onUnderstand={result => { if (result.category) setCategory(categories.find(item => item.toLowerCase() === result.category?.toLowerCase()) || 'Other') }} /></div></div></div><div className="form-step"><span>2</span><div><strong>{t.what}</strong><FieldVoice language={language} label={t.what} value={description} onChange={setDescription} onUnderstand={result => { if (result.problem) setDescription(result.problem) }} multiline /></div></div><div className="form-step"><span>3</span><div><strong>Where is the problem?</strong><FieldVoice language={language} label="Where is the problem?" value={location} onChange={setLocation} onUnderstand={result => { if (result.location) setLocation(result.location) }} /></div></div><div className="form-step"><span>4</span><div><strong>Additional details</strong><FieldVoice language={language} label="Tell us more about the problem..." value={details} onChange={setDetails} multiline /></div></div><div className="form-step"><span>5</span><div><strong>How urgent is this?</strong><div className="severity-options">{(['Critical', 'High', 'Medium', 'Low'] as const).map(item => <button type="button" key={item} className={severity === item ? 'selected' : ''} onClick={() => setSeverity(item)}>{item}</button>)}</div><label className="affected-label">People affected <input type="number" min="1" value={affected} onChange={event => setAffected(event.target.value)} placeholder="Approximate number" /></label></div></div></div><label className="media-upload"><strong>Add a photo or video (optional)</strong><input type="file" accept="image/jpeg,image/png,image/webp,video/mp4,video/quicktime,video/webm" multiple onChange={handleFiles} />{files.length > 0 && <small>{files.length} file{files.length === 1 ? '' : 's'} ready to attach</small>}</label><Button className="button-primary form-submit" type="submit" disabled={!category || !description}><Send data-icon="inline-start" /> {t.submit}</Button></form> }

function LegacyReportForm({ language, onSubmit }: { language: Language; onSubmit: (issue: Issue) => void }) { const t = translations[language]; const [category, setCategory] = useState('Water Supply'); const [description, setDescription] = useState(''); const [location, setLocation] = useState(''); const [severity, setSeverity] = useState('High'); const [affected, setAffected] = useState(''); const [files, setFiles] = useState<File[]>([]); const [submitted, setSubmitted] = useState(false); const handleFiles = (event: React.ChangeEvent<HTMLInputElement>) => { const selected = Array.from(event.target.files ?? []); const valid = selected.filter(file => /^(image\/(jpeg|png|webp)|video\/(mp4|quicktime|webm))$/.test(file.type) && file.size <= 25 * 1024 * 1024); setFiles(previous => [...previous, ...valid].slice(0, 5)); event.target.value = '' }; const handleSubmit = (event: React.FormEvent) => { event.preventDefault(); const id = `CIV-${10300 + Math.floor(Math.random() * 100)}`; onSubmit({ id, title: description || `${category} issue`, category, location: location || 'Location shared from map', priority: severity as Issue['priority'], status: 'New', affected: Number(affected) || 1, reports: 1, date: 'Just now', department: category === 'Water Supply' ? 'Water Department' : category === 'Garbage' ? 'Sanitation' : 'Municipality', officer: 'Awaiting assignment', score: 64, color: 'high' }); setSubmitted(true) }; if (submitted) return <div className="submitted-state"><div className="submitted-icon"><CheckCircle2 /></div><p className="eyebrow">Report received</p><h2>Thank you for speaking up.</h2><p>Your issue is now in the civic response queue. We will keep you updated.</p><Button className="button-primary" onClick={() => { setSubmitted(false); setDescription(''); setFiles([]) }}>Report another issue <ArrowRight data-icon="inline-end" /></Button></div>; return <form className="report-form" onSubmit={handleSubmit}><div className="step-list"><div className="form-step"><span>1</span><div><strong><Mic /> {t.what}</strong><p>Speak or type the problem in your own language.</p></div></div><div className="form-step"><span>2</span><div><strong><MapPin /> {t.where}</strong><p>Use a landmark, map or current location.</p></div></div><div className="form-step"><span>3</span><div><strong><Upload /> Show the problem</strong><p>Add JPG, JPEG, PNG, WEBP, MP4, MOV or WEBM.</p></div></div></div><VoiceRecorder language={language} onTranscript={setDescription} /><label>Issue category<select value={category} onChange={e => setCategory(e.target.value)}><option>Water Supply</option><option>Road / Pothole</option><option>Drainage</option><option>Garbage</option><option>Streetlight</option><option>Sewage</option><option>Public Safety / Infrastructure</option><option>Other</option></select></label><label><span className="question-label">{t.what}</span><textarea value={description} onChange={e => setDescription(e.target.value)} placeholder="Example: No water in our street since yesterday..." required /></label><div className="form-grid"><label><span className="question-label">{t.where}</span><div className="input-with-icon"><MapPin /><input value={location} onChange={e => setLocation(e.target.value)} placeholder="Street, landmark or area" required /></div></label><Button type="button" variant="outline" className="location-button" onClick={() => setLocation('My current location · Ward 12')}><LocateFixed data-icon="inline-start" /> Use current location</Button></div><div className="form-grid"><label>Priority<select value={severity} onChange={e => setSeverity(e.target.value)}><option>Low</option><option>Medium</option><option>High</option><option>Critical</option></select></label><label>People affected <span className="optional">Approximate</span><input type="number" min="1" value={affected} onChange={e => setAffected(e.target.value)} placeholder="e.g. 50" /></label></div><label><span className="question-label">Show the problem</span><div className="upload-box media-upload"><Upload /><span>Add photo or video</span><small>JPG, JPEG, PNG, WEBP, MP4, MOV, WEBM · up to 25 MB each</small><input type="file" multiple accept="image/jpeg,image/png,image/webp,video/mp4,video/quicktime,video/webm" onChange={handleFiles} /></div></label>{files.length > 0 && <div className="media-previews">{files.map((file, index) => <div className="media-preview" key={`${file.name}-${index}`}>{file.type.startsWith('video') ? <video src={URL.createObjectURL(file)} controls /> : <img src={URL.createObjectURL(file)} alt={`Selected evidence ${index + 1}`} />}<button type="button" onClick={() => setFiles(files.filter((_, fileIndex) => fileIndex !== index))}><X /></button><span>Ready</span></div>)}</div>}<label><span className="question-label">{t.details}</span><textarea placeholder="Anything else that can help the response team?" /></label><Button type="submit" className="button-primary button-submit"><Check data-icon="inline-start" /> {t.submit} <ArrowRight data-icon="inline-end" /></Button><p className="privacy-note"><ShieldCheck /> Your exact location and contact details stay private.</p></form> }

function NotificationCenter({ language, notifications, onRead }: { language: Language; notifications: Notification[]; onRead: (id: string) => void }) { const t = translations[language]; const [filter, setFilter] = useState('All'); const visible = notifications.filter(item => filter === 'All' || item.kind === filter || (filter === 'Unread' && item.unread)); return <div className="page-shell notification-page"><div className="page-heading row-heading"><div><p className="eyebrow">Stay informed</p><h1>{t.notification}</h1><p>Important updates for your nearby and saved areas.</p></div><Button variant="outline"><Settings2 data-icon="inline-start" /> {t.settings}</Button></div><div className="notification-controls">{['All', 'Unread', 'Critical', 'Nearby', 'Road Alert', 'Water Alert'].map(item => <button key={item} className={filter === item ? 'active' : ''} onClick={() => setFilter(item)}>{item}{item === 'Unread' && <b>{notifications.filter(note => note.unread).length}</b>}</button>)}</div><div className="alert-settings"><div><Bell /><div><strong>{t.nearby}</strong><p>Use your permission and saved areas to send only relevant alerts.</p></div></div><label className="switch"><input type="checkbox" defaultChecked /><span /></label></div><div className="saved-areas"><strong>My Areas</strong><span>⌂ Home · Ward 12</span><span>College · Green Park</span><button><Plus /> Add area</button></div><div className="notifications-list">{visible.map(item => <article className={`notification-card ${item.kind === 'Critical' ? 'critical' : ''} ${item.unread ? 'unread' : ''}`} key={item.id}><div className="notification-icon">{item.kind === 'Water Alert' ? <Droplets /> : item.kind === 'Resolution' ? <CheckCircle2 /> : <Road />}</div><div className="notification-copy"><div className="notification-meta"><span>{item.kind}</span><span>{item.time}</span>{item.unread && <b>Unread</b>}</div><h2>{item.title}</h2><p>{item.description}</p><small><MapPin /> {item.location} · {item.issueId}</small></div><div className="notification-actions"><Button variant="outline" size="sm" onClick={() => onRead(item.id)}>View details</Button>{item.kind === 'Critical' && <Button variant="ghost" size="sm">Alternative route</Button>}</div></article>)}</div><div className="notification-preferences"><h2>Notification Settings</h2><div className="preference-grid">{['Critical alerts', 'Nearby road alerts', 'Water supply alerts', 'Road work alerts', 'Resolution updates', 'Other important civic alerts'].map(item => <label key={item}><input type="checkbox" defaultChecked={item !== 'Other important civic alerts'} /> {item}</label>)}</div></div></div> }

function Timeline({ issue }: { issue: Issue }) { return <div className="timeline"><div><span><Check /></span><p>03 Oct · 10:20 AM</p><strong>Issue submitted</strong></div><div><span><Check /></span><p>03 Oct · 11:00 AM</p><strong>Verified</strong></div><div><span><Check /></span><p>03 Oct · 11:15 AM</p><strong>Assigned to {issue.department}</strong></div><div><span><Check /></span><p>04 Oct · 09:00 AM</p><strong>Work started</strong></div><div><span><Check /></span><p>05 Oct · 04:30 PM</p><strong>Marked resolved</strong></div></div> }
function AuthorityDashboard({ issues, onUpdate, notifications }: { issues: Issue[]; onUpdate: (issue: Issue) => void; notifications: Notification[] }) { const [query, setQuery] = useState(''); const [statusFilter, setStatusFilter] = useState<Status | 'All'>('All'); const [selected, setSelected] = useState<Issue | null>(null); const filtered = issues.filter(issue => (statusFilter === 'All' || issue.status === statusFilter) && `${issue.id} ${issue.title} ${issue.location}`.toLowerCase().includes(query.toLowerCase())); const active = issues.filter(issue => !['Resolved', 'Closed'].includes(issue.status)); const completed = issues.filter(issue => ['Resolved', 'Closed'].includes(issue.status)); const stats = [{ label: 'Critical', value: issues.filter(i => i.priority === 'Critical').length, icon: Flame, tone: 'red', filter: 'All' as const }, { label: 'New / Verification', value: issues.filter(i => ['New', 'Under Verification'].includes(i.status)).length, icon: AlertTriangle, tone: 'orange', filter: 'Under Verification' as const }, { label: 'Assigned', value: issues.filter(i => i.status === 'Assigned').length, icon: FileText, tone: 'blue', filter: 'Assigned' as const }, { label: 'In Progress', value: issues.filter(i => i.status === 'In Progress').length, icon: Gauge, tone: 'violet', filter: 'In Progress' as const }, { label: 'Resolved', value: completed.length, icon: CheckCircle2, tone: 'green', filter: 'Resolved' as const }]; return <div className="authority-page"><div className="dashboard-heading"><div><p className="eyebrow">Municipal operations</p><h1>Good morning, Ananya.</h1><p>One clear view of every issue, owner and next action.</p></div><div className="authority-actions"><span className="unread-count"><Bell /> {notifications.filter(note => note.unread).length} unread</span><Button variant="outline"><FileText data-icon="inline-start" /> Export report</Button></div></div><section className="action-required"><div><span className="critical-pulse"><Zap /></span><div><p className="eyebrow">Action required</p><h2>2 critical issues need attention</h2><p>5 new issues await verification · 3 verified issues await department assignment · 4 assigned issues have not started</p></div></div><Button className="button-primary" onClick={() => setStatusFilter('Under Verification')}>Review now <ArrowRight data-icon="inline-end" /></Button></section><div className="stat-grid">{stats.map(stat => <button className="stat-card stat-card-button" key={stat.label} onClick={() => setStatusFilter(stat.filter)}><div className={`stat-icon ${stat.tone}`}><stat.icon /></div><div><span>{stat.label}</span><strong>{stat.value}</strong></div><TrendingUp className="stat-trend" /></button>)}</div><section className="dashboard-card lifecycle-card"><div className="section-heading"><div><h2>Issue lifecycle</h2><p>Each issue has one current status at a time.</p></div><span className="status-guide"><CircleHelp /> Status guide</span></div><div className="lifecycle">{(['New', 'Under Verification', 'Verified', 'Assigned', 'In Progress', 'Resolved', 'Closed'] as Status[]).map((status, index) => <div key={status}><span>{index + 1}</span><strong>{status}</strong></div>)}</div><p className="lifecycle-help">New = submitted · Under Verification = being checked · Verified = confirmed · Assigned = owner selected · In Progress = work started · Resolved = department reports fixed · Closed = resolution confirmed</p></section><div className="dashboard-grid"><section className="dashboard-card"><div className="section-heading"><div><h2>Critical issue alerts</h2><p>Reminders and escalation prevent missed safety issues.</p></div><span className="live-pill"><Radio /> Live</span></div><div className="authority-alert-list">{notifications.filter(note => note.unread).slice(0, 2).map(note => <div className="authority-alert" key={note.id}><AlertTriangle /><div><strong>{note.title}</strong><p>{note.issueId} · {note.location} · Reported {note.time}</p><small>Priority: Critical · Affected: 450 · Required: Water Department</small></div><Button size="sm" className="button-primary" onClick={() => setSelected(issues.find(issue => issue.id === note.issueId) ?? issues[0])}>View issue</Button></div>)}</div></section><section className="dashboard-card mini-map"><div className="section-heading"><div><h2>Issue activity</h2><p>Live reports across your area</p></div></div><MapPanel compact /></section></div><section className="dashboard-card issue-table-section"><div className="section-heading"><div><h2>Active Issues</h2><p>New, verification, verified, assigned and in-progress work.</p></div><div className="table-tools"><Search /><input placeholder="Search issues" value={query} onChange={event => setQuery(event.target.value)} /><select value={statusFilter} onChange={event => setStatusFilter(event.target.value as Status | 'All')}><option value="All">All statuses</option>{(['New', 'Under Verification', 'Verified', 'Assigned', 'In Progress'] as Status[]).map(status => <option key={status}>{status}</option>)}</select></div></div><div className="issue-table">{filtered.filter(issue => !['Resolved', 'Closed'].includes(issue.status)).map(issue => <div className="issue-row" key={issue.id}><div><strong>{issue.id}</strong><span>{issue.title}</span><small><MapPin /> {issue.location}</small></div><StatusBadge status={issue.status} /><div><small>Department</small><strong>{issue.department}</strong><small>Officer: {issue.officer}</small></div><div><small>Last updated</small><strong>{issue.date}</strong><small>Next: {issue.status === 'Assigned' ? 'Start work' : issue.status === 'In Progress' ? 'Complete repair' : 'Review'}</small></div><Button size="sm" variant="outline" onClick={() => setSelected(issue)}>Open</Button></div>)}</div></section><section className="dashboard-card completed-section"><div className="section-heading"><div><h2>Completed Issues</h2><p>Permanent resolution history and department accountability.</p></div><span className="completed-count"><CheckCircle2 /> {completed.length} records</span></div>{completed.map(issue => <div className="completed-card" key={issue.id}><div className="completed-top"><div><strong>{issue.id}</strong><h3>{issue.title}</h3><p><MapPin /> {issue.location}</p></div><StatusBadge status={issue.status} /></div><div className="completed-details"><span>Resolved by<strong>{issue.department}</strong></span><span>Assigned<strong>{issue.officer}</strong></span><span>Reported<strong>{issue.date}</strong></span><span>Resolution<strong>Repair completed and evidence submitted.</strong></span></div><Timeline issue={issue} /><div className="confirmation"><CheckCircle2 /> Citizen confirmation: <strong>{issue.status === 'Resolved' ? 'Pending confirmation' : 'Confirmed resolved'}</strong></div></div>)}</section>{selected && <div className="issue-drawer"><button className="drawer-close" onClick={() => setSelected(null)}><X /></button><p className="eyebrow">Issue review</p><h2>{selected.id}</h2><div className="current-status"><span>Current status</span><StatusBadge status={selected.status} /></div><h3>{selected.title}</h3><p><MapPin /> {selected.location}</p><div className="drawer-fields"><label>Assigned department<select value={selected.department} onChange={event => onUpdate({ ...selected, department: event.target.value })}><option>Water Department</option><option>Public Works</option><option>Drainage Department</option><option>Sanitation</option></select></label><label>Current status<select value={selected.status} onChange={event => { const updated = { ...selected, status: event.target.value as Status }; onUpdate(updated); setSelected(updated) }}>{(['New', 'Under Verification', 'Verified', 'Assigned', 'In Progress', 'Resolved', 'Closed'] as Status[]).map(status => <option key={status}>{status}</option>)}</select></label></div><div className="drawer-next"><strong>Next action</strong><p>{selected.status === 'Assigned' ? 'Start work and add evidence.' : selected.status === 'In Progress' ? 'Complete repair and submit resolution evidence.' : 'Review and move to the next status.'}</p></div><Button className="button-primary" onClick={() => setSelected(null)}>Save update</Button></div>}</div> }

function TrackPanel({ issue }: { issue: Issue }) { const steps: Status[] = ['New', 'Under Verification', 'Verified', 'Assigned', 'In Progress', 'Resolved', 'Closed']; const current = Math.max(0, steps.indexOf(issue.status)); return <div className="track-panel"><div className="track-header"><div><p className="eyebrow">Report tracking</p><h2>{issue.id}</h2><p>{issue.title} · {issue.location}</p></div><StatusBadge status={issue.status} /></div><div className="tracker">{steps.map((step, index) => <div className={`tracker-step ${index <= current ? 'done' : ''} ${index === current ? 'current' : ''}`} key={step}><div className="tracker-node">{index < current ? <Check /> : index === current ? <span /> : index + 1}</div><span>{step}</span>{index < steps.length - 1 && <div className="tracker-line" />}</div>)}</div><div className="track-detail"><div><span className="detail-label">Last updated</span><strong>Today, 11:24 AM</strong></div><div><span className="detail-label">Assigned to</span><strong>{issue.department}</strong></div><div><span className="detail-label">Expected update</span><strong>Within 2 days</strong></div></div></div> }

type PortalRole = 'CITIZEN' | 'AUTHORITY' | 'WORKER'
type DemoSession = { role: 'AUTHORITY' | 'WORKER'; name: string; department?: string }
const demoWorkers = [{ name: 'Ravi Kumar', id: 'WRK-003', department: 'Electrical', status: 'Available', active: 0 }, { name: 'Sana Begum', id: 'WRK-008', department: 'Electrical', status: 'Busy', active: 3 }, { name: 'Kiran Rao', id: 'WRK-011', department: 'Water Supply', status: 'Available', active: 1 }]

function RoleSelection({ onSelect }: { onSelect: (role: PortalRole) => void }) { return <main className="role-selection"><div className="role-portal-link"><ShieldCheck /><button type="button" onClick={() => onSelect('AUTHORITY')}>Authority Dashboard</button></div><div className="role-selection-card"><Logo /><p className="eyebrow">Civic administration platform</p><h1>Welcome to CivicConnect</h1><p className="role-copy">Who are you?</p><div className="role-grid"><button onClick={() => onSelect('CITIZEN')} className="role-card"><UserRound /><strong>Citizen</strong><span>Report and track civic issues</span></button><button onClick={() => onSelect('AUTHORITY')} className="role-card"><ShieldCheck /><strong>Authority</strong><span>Manage issues, departments and workers</span></button><button onClick={() => onSelect('WORKER')} className="role-card"><Settings2 /><strong>Worker</strong><span>View and complete assigned civic work</span></button></div></div></main> }
function PortalLogin({ kind, onSuccess, onBack }: { kind: 'AUTHORITY' | 'WORKER'; onSuccess: (session: DemoSession) => void; onBack: () => void }) { const authority = kind === 'AUTHORITY'; const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [show, setShow] = useState(false); const [error, setError] = useState(''); const submit = (event: React.FormEvent) => { event.preventDefault(); if (!email.trim()) return setError('Enter your official email or ID.'); if (!password) return setError('Enter your password.'); if (authority && (email === 'authority@civicconnect.demo' || email === 'demo') && password === 'demo-access') return onSuccess({ role: 'AUTHORITY', name: 'Authority Admin' }); if (!authority && (email === 'WRK-003' || email === 'worker@civicconnect.demo') && password === 'demo-access') return onSuccess({ role: 'WORKER', name: 'Ravi Kumar', department: 'Electrical' }); setError('Authentication failed. Check your details and try again.') }; return <main className="portal-login"><div className="portal-login-card"><Logo /><div className="portal-login-heading"><p className="eyebrow">{authority ? 'Authority Portal' : 'Worker Portal'}</p><h1>{authority ? 'Authorized access for civic administration' : 'Your assigned civic work'}</h1><p>{authority ? 'Sign in to manage reports, departments and assignments.' : 'Sign in to view work assigned to your registered profile.'}</p></div><form onSubmit={submit} className="portal-form"><label>{authority ? 'Official Email / Authority ID' : 'Worker ID / Email'}<input value={email} onChange={event => setEmail(event.target.value)} autoComplete="username" /></label><label>Password<div className="password-field"><input type={show ? 'text' : 'password'} value={password} onChange={event => setPassword(event.target.value)} autoComplete="current-password" /><button type="button" onClick={() => setShow(!show)}>{show ? 'Hide' : 'Show'}</button></div></label>{authority && <label className="remember"><input type="checkbox" /> Remember me</label>}{error && <p className="form-error" role="alert">{error}</p>}<Button type="submit" className="button-primary button-large">Login</Button></form><button className="demo-access" onClick={() => onSuccess(authority ? { role: 'AUTHORITY', name: 'Authority Admin' } : { role: 'WORKER', name: 'Ravi Kumar', department: 'Electrical' })}>Demo {authority ? 'Authority' : 'Worker'} Access – Hackathon</button><div className="login-links"><button onClick={() => setError('Password recovery is available through your registered administrator.')}>Forgot Password?</button><button onClick={onBack}>Back to Citizen Portal</button></div><p className="demo-hint">Demo credentials: {authority ? 'demo / demo-access' : 'WRK-003 / demo-access'}</p></div></main> }
function WorkerPortal({ session, issues, onUpdate, onLogout }: { session: DemoSession; issues: Issue[]; onUpdate: (issue: Issue) => void; onLogout: () => void }) { const assigned = issues.filter(issue => issue.status === 'Assigned' || issue.status === 'In Progress'); return <main className="portal-page"><div className="portal-top"><div><p className="eyebrow">Worker Portal</p><h1>Welcome, {session.name}</h1><p>Department: <strong>{session.department}</strong></p></div><Button variant="outline" onClick={onLogout}>Logout</Button></div><div className="portal-stats"><div><strong>{assigned.length}</strong><span>Assigned Issues</span></div><div><strong>{assigned.filter(issue => issue.status === 'In Progress').length}</strong><span>In Progress</span></div><div><strong>{issues.filter(issue => issue.status === 'Resolved').length}</strong><span>Completed</span></div><div><strong>{assigned.filter(issue => issue.priority === 'Critical' || issue.priority === 'High').length}</strong><span>High Priority</span></div></div><section className="portal-panel"><div className="section-heading"><div><p className="eyebrow">My Assigned Issues</p><h2>Current civic work</h2></div></div><div className="portal-list">{assigned.map(issue => <article className="portal-list-item" key={issue.id}><div><strong>{issue.id} · {issue.title}</strong><p>{issue.location} · {issue.priority} priority</p></div><Button className="button-primary" onClick={() => onUpdate({ ...issue, status: issue.status === 'Assigned' ? 'In Progress' : 'Resolved' })}>{issue.status === 'Assigned' ? 'Start Work' : 'Mark as Resolved'}</Button></article>)}</div></section></main> }
function RolePortal({ session, issues, onUpdate, onLogout }: { session: DemoSession; issues: Issue[]; onUpdate: (issue: Issue) => void; onLogout: () => void }) { const [department, setDepartment] = useState('All'); const [selectedWorker, setSelectedWorker] = useState(''); const departments = ['Roads', 'Electrical', 'Water Supply', 'Drainage', 'Sanitation', 'Public Works']; const available = demoWorkers.filter(worker => department === 'All' || worker.department === department); const openIssues = issues.filter(issue => !['Resolved', 'Closed'].includes(issue.status)); const assign = (issue: Issue) => { const worker = demoWorkers.find(item => item.name === selectedWorker) ?? available.find(item => item.status === 'Available'); if (worker) onUpdate({ ...issue, status: 'Assigned', department: worker.department, officer: worker.name }) }; return <main className="portal-page"><div className="portal-top"><div><p className="eyebrow">Authority Portal · {session.name}</p><h1>Authority Dashboard</h1><p>Review civic reports, workforce availability and assignments.</p></div><Button variant="outline" onClick={onLogout}>Logout</Button></div><div className="portal-stats">{[['Total Issues', issues.length], ['New Reports', issues.filter(issue => issue.status === 'New').length], ['Critical Issues', issues.filter(issue => issue.priority === 'Critical').length], ['Assigned', issues.filter(issue => issue.status === 'Assigned').length], ['In Progress', issues.filter(issue => issue.status === 'In Progress').length], ['Resolved', issues.filter(issue => issue.status === 'Resolved').length]].map(([label, value]) => <div key={String(label)}><strong>{String(value)}</strong><span>{label}</span></div>)}</div><div className="portal-columns"><section className="portal-panel"><div className="section-heading"><div><p className="eyebrow">Action Required</p><h2>Issue assignment</h2></div></div>{openIssues.map(issue => <article className="portal-list-item" key={issue.id}><div><strong>{issue.id} · {issue.title}</strong><p>{issue.location} · {issue.priority} priority · {issue.status}</p></div><div className="assign-controls"><select value={selectedWorker} onChange={event => setSelectedWorker(event.target.value)}><option value="">Choose worker</option>{available.map(worker => <option key={worker.id} value={worker.name}>{worker.name} · {worker.status} · {worker.active} active</option>)}</select><Button className="button-primary" onClick={() => assign(issue)}>Assign Issue</Button></div></article>)}</section><section className="portal-panel"><p className="eyebrow">Departments</p><h2>Workforce overview</h2><select className="department-select" value={department} onChange={event => setDepartment(event.target.value)}><option>All</option>{departments.map(item => <option key={item}>{item}</option>)}</select><div className="worker-list">{available.map(worker => <div className="worker-row" key={worker.id}><span className={`worker-status ${worker.status.toLowerCase()}`} /><div><strong>{worker.name}</strong><p>{worker.id} · {worker.department}</p></div><small>{worker.status}<br />{worker.active} active issues</small></div>)}</div></section></div></main> }

export default function Page() { const [activeNav, setActiveNav] = useState('Home'); const [portal, setPortal] = useState<PortalRole | null>(null); const [session, setSession] = useState<DemoSession | null>(null); const [issues, setIssues] = useState(initialIssues); const [authReady, setAuthReady] = useState(false); const [language, setLanguage] = useState<Language>(() => { if (typeof window === 'undefined') return 'EN'; const saved = window.localStorage.getItem('civicconnect-language'); return saved === 'TE' || saved === 'HI' ? saved : 'EN' }); const [mobileNav, setMobileNav] = useState(false); const [notifications, setNotifications] = useState(sampleNotifications); const t = translations[language]; useEffect(() => { let mounted = true; void supabaseBrowser.auth.getUser().then(({ data }) => { const user = data.user; const role = user?.app_metadata?.role; if (!mounted) return; if (user && (role === 'AUTHORITY' || role === 'WORKER')) { setSession({ role, name: user.user_metadata?.full_name || user.email || (role === 'WORKER' ? 'Registered Worker' : 'Authority Admin'), department: role === 'WORKER' ? user.app_metadata?.department : undefined }); setPortal(role) } setAuthReady(true) }); return () => { mounted = false } }, []); useEffect(() => { window.localStorage.setItem('civicconnect-language', language); applyGlobalLanguage(language) }, [language, activeNav, issues, notifications]); if (portal === null) return <RoleSelection onSelect={role => { if (role === 'CITIZEN') setPortal('CITIZEN'); else setPortal(role) }} />; if (portal === 'AUTHORITY' && !session) return <PortalLogin kind="AUTHORITY" onBack={() => setPortal('CITIZEN')} onSuccess={next => { setSession(next); setPortal('AUTHORITY') }} />; if (portal === 'WORKER' && !session) return <PortalLogin kind="WORKER" onBack={() => setPortal('CITIZEN')} onSuccess={next => { setSession(next); setPortal('WORKER') }} />; if (portal === 'AUTHORITY' && session?.role === 'AUTHORITY') return <RolePortal session={session} issues={issues} onUpdate={updated => setIssues(previous => previous.map(issue => issue.id === updated.id ? updated : issue))} onLogout={() => { void supabaseBrowser.auth.signOut(); setSession(null); setPortal('AUTHORITY') }} />; if (portal === 'WORKER' && session?.role === 'WORKER') return <WorkerPortal session={session} issues={issues} onUpdate={updated => setIssues(previous => previous.map(issue => issue.id === updated.id ? updated : issue))} onLogout={() => { setSession(null); setPortal('WORKER') }} />; const trackedIssue = issues[0]; const visibleIssues = issues.slice(0, 5); const addIssue = (issue: Issue) => { setIssues(previous => [issue, ...previous]); setActiveNav('Track Issue') }; const renderContent = () => { if (activeNav === 'Authority Dashboard') return <AuthorityDashboard issues={issues} onUpdate={updated => setIssues(previous => previous.map(issue => issue.id === updated.id ? updated : issue))} notifications={notifications} />; if (activeNav === 'Report Issue') return <div className="page-shell narrow"><div className="page-heading"><p className="eyebrow">Make a difference</p><h1>{t.reportTitle}</h1><p>{t.reportCopy}</p></div><div className="report-layout"><ReportForm language={language} onSubmit={addIssue} /><aside className="report-aside"><div className="aside-tip"><Sparkles /><strong>Good to know</strong><p>Adding a photo, location and number of people affected helps your report reach the right team.</p></div><MapPanel compact /></aside></div></div>; if (activeNav === 'Track Issue') return <div className="page-shell"><div className="page-heading row-heading"><div><p className="eyebrow">Keep up with progress</p><h1>{t.track}</h1><p>See exactly what happens after you speak up.</p></div><div className="track-search"><Search /><input placeholder="Enter complaint ID" defaultValue={trackedIssue.id} /><Button className="button-primary">Track</Button></div></div><TrackPanel issue={trackedIssue} /><div className="section-heading public-heading"><div><h2>Reports you support</h2><p>When neighbors stand together, issues get noticed faster.</p></div></div><div className="issue-grid">{visibleIssues.slice(1, 3).map(issue => <IssueCard key={issue.id} issue={issue} />)}</div></div>; if (activeNav === 'Civic Map') return <div className="page-shell"><div className="page-heading row-heading"><div><p className="eyebrow">See your neighborhood</p><h1>{t.map}</h1><p>Explore public reports and follow issues near you.</p></div><Button variant="outline"><LocateFixed data-icon="inline-start" /> Near me</Button></div><MapPanel /><div className="section-heading public-heading"><div><h2>Issues on the map</h2><p>Tap an issue to see how your community is affected.</p></div></div><div className="issue-grid">{visibleIssues.map(issue => <IssueCard key={issue.id} issue={issue} />)}</div></div>; if (activeNav === 'Alerts') return <NotificationCenter language={language} notifications={notifications} onRead={id => setNotifications(previous => previous.map(note => note.id === id ? { ...note, unread: false } : note))} />; if (activeNav === 'Help') return <div className="page-shell"><div className="page-heading"><p className="eyebrow">We are here to help</p><h1>How can we help?</h1><p>Simple answers to common questions.</p></div><div className="help-grid">{['How do I report an issue?', 'How do I track my report?', 'Can I report without a photo?', 'When will my issue be fixed?'].map((question, index) => <div className="help-card" key={question}><div className="help-number">0{index + 1}</div><h2>{question}</h2><p>Tap Report Issue, add a few details and submit. You will get a complaint ID immediately.</p><ArrowRight /></div>)}</div></div>; return <div className="home-page"><section className="hero"><div className="hero-copy"><div className="welcome-pill"><span className="pulse-dot" /> Your neighborhood, heard</div><h1>{t.hero.split('\n').map((line, index) => <span key={line}>{line}{index === 0 && <br />}</span>)}</h1><p>{t.heroCopy}</p><div className="hero-actions"><Button className="button-primary button-large" onClick={() => setActiveNav('Report Issue')}><Plus data-icon="inline-start" /> {t.report} <ArrowRight data-icon="inline-end" /></Button><Button variant="outline" className="button-large" onClick={() => setActiveNav('Track Issue')}><FileText data-icon="inline-start" /> {t.track}</Button></div></div><div className="hero-visual"><div className="hero-orbit orbit-one" /><div className="hero-orbit orbit-two" /><div className="hero-circle"><div className="hero-house"><Home /></div></div><div className="floating-card card-alert"><div className="floating-icon red"><Droplets /></div><div><strong>Water supply issue</strong><span>450 people affected</span></div><CheckCircle2 className="floating-check" /></div><div className="floating-card card-resolved"><div className="floating-icon green"><Lightbulb /></div><div><strong>Streetlight fixed</strong><span>Thanks to 62 reports</span></div><CheckCircle2 className="floating-check" /></div></div></section><section className="home-section quick-actions"><div className="section-heading"><div><p className="eyebrow">Start here</p><h2>Important civic updates</h2></div><button className="voice-button" onClick={() => setActiveNav('Alerts')}><Bell /> {t.notification} <span>›</span></button></div><div className="action-grid"><button className="action-card" onClick={() => setActiveNav('Report Issue')}><span className="action-icon blue"><Plus /></span><span className="action-copy"><strong>{t.report}</strong><small>Voice, text or media</small></span><ArrowRight className="action-arrow" /></button><button className="action-card" onClick={() => setActiveNav('Alerts')}><span className="action-icon orange"><Bell /></span><span className="action-copy"><strong>{t.nearby}</strong><small>2 unread safety alerts</small></span><ArrowRight className="action-arrow" /></button><button className="action-card" onClick={() => setActiveNav('Track Issue')}><span className="action-icon purple"><FileText /></span><span className="action-copy"><strong>{t.track}</strong><small>Follow your report</small></span><ArrowRight className="action-arrow" /></button><button className="action-card" onClick={() => setActiveNav('Civic Map')}><span className="action-icon teal"><MapPin /></span><span className="action-copy"><strong>{t.map}</strong><small>See nearby issues</small></span><ArrowRight className="action-arrow" /></button></div></section></div> }; return <div className="app-shell"><header className="site-header"><div className="header-inner"><button className="mobile-menu" onClick={() => setMobileNav(!mobileNav)} aria-label="Open menu"><Menu /></button><button className="logo-button" onClick={() => setActiveNav('Home')}><Logo /></button><nav className={mobileNav ? 'nav-menu open' : 'nav-menu'}>{navItems.map(item => <button className={activeNav === item.label ? 'nav-link active' : 'nav-link'} key={item.label} onClick={() => { setActiveNav(item.label); setMobileNav(false) }}><item.icon />{t[item.label === 'Home' ? 'home' : item.label === 'Report Issue' ? 'report' : item.label === 'Track Issue' ? 'track' : item.label === 'Civic Map' ? 'map' : item.label.toLowerCase()]}</button>)}</nav><div className="header-actions"><button className="language-button" onClick={() => setLanguage(language === 'EN' ? 'TE' : language === 'TE' ? 'HI' : 'EN')}><Languages /> {language === 'EN' ? 'English' : language === 'TE' ? 'తెలుగు' : 'हिन्दी'}<ChevronDown /></button><Button variant="outline" className="authority-button" onClick={() => setActiveNav('Authority Dashboard')}><BarChart3 data-icon="inline-start" /> Authority dashboard</Button><button className="profile-button"><span>A</span></button></div></div></header><main>{renderContent()}</main><footer className="site-footer"><Logo /><p>Built for communities that care.</p><div><button>Privacy</button><button>Accessibility</button><button>Contact</button></div></footer></div> }

type RecognitionLike = { lang: string; continuous: boolean; interimResults: boolean; start(): void; stop(): void; onresult: ((event: { results: { [index: number]: { [index: number]: { transcript: string } } } }) => void) | null; onerror?: (() => void) | null; onend: (() => void) | null }
